254	/// Compile a single time.
255	///
256	/// Returns whether it compiled without errors.
257	#[typst_macros::time(name = "compile once")]
258	pub fn compile_once(
259	    world: &mut SystemWorld,
260	    config: &mut CompileConfig,
261	) -> HintedStrResult<()> {
262	    let start = std::time::Instant::now();
263	    if config.watching {
264	        Status::Compiling.print(config).unwrap();
265	    }
266	
267	    let Warned { output, mut warnings } = compile_and_export(world, config);
268	
269	    // Add static warnings (for deprecated CLI flags and such).
270	    for warning in &config.warnings {
271	        warnings.push(
272	            SourceDiagnostic::warning(Span::detached(), warning.message())
273	                .with_hints(warning.hints().iter().map(Into::into)),
274	        );
275	    }
276	
277	    match &output {
278	        // Print success message and possibly warnings.
279	        Ok(_) => {
280	            let duration = start.elapsed();
281	            if config.watching {
282	                if warnings.is_empty() {
283	                    Status::Success(duration).print(config).unwrap();
284	                } else {
285	                    Status::PartialSuccess(duration).print(config).unwrap();
286	                }
287	            }
288	
289	            print_diagnostics(world, &[], &warnings, config.diagnostic_format)
290	                .map_err(|err| eco_format!("failed to print diagnostics ({err})"))?;
291	
292	            open_output(config)?;
293	        }
294	
295	        // Print failure message and diagnostics.
296	        Err(errors) => {
297	            set_failed();
298	
299	            if config.watching {
300	                Status::Error.print(config).unwrap();
301	            }
302	
303	            print_diagnostics(world, errors, &warnings, config.diagnostic_format)
304	                .map_err(|err| eco_format!("failed to print diagnostics ({err})"))?;
305	        }
306	    }
307	
308	    if let Some(dest) = &config.deps {
309	        write_deps(world, dest, config.deps_format, output.as_deref().ok())
310	            .map_err(|err| eco_format!("failed to create dependency file ({err})"))?;
311	    }
312	
313	    Ok(())
314	}
