390	/// Export to a bundle, a collection of files in a directory.
391	fn export_bundle(bundle: Bundle, config: &CompileConfig) -> SourceResult<Vec<Output>> {
392	    let options = BundleOptions {
393	        html: html_options(config),
394	        pdf: pdf_options(config),
395	        png: png_options(config),
396	        svg: svg_options(config),
397	    };
398	
399	    let fs = typst_bundle::export(&bundle, &options)?;
400	    let root = match &config.output {
401	        Output::Path(path) => path,
402	        Output::Stdout => {
403	            bail!(Span::detached(), "cannot write bundle to standard output")
404	        }
405	    };
406	
407	    let outputs = write_virtual_fs(root, &fs).at(Span::detached())?;
408	
409	    #[cfg(feature = "http-server")]
410	    if let Some(server) = &config.server {
411	        server.set_bundle(bundle, fs);
412	    }
413	
414	    Ok(outputs)
415	}
