417	/// Writes a bundle's files to disk.
418	fn write_virtual_fs(root: &Path, fs: &VirtualFs) -> StrResult<Vec<Output>> {
419	    std::fs::create_dir_all(root)
420	        .map_err(|err| eco_format!("failed to create output directory ({err})"))?;
421	
422	    fs.par_iter()
423	        .map(|(path, data)| {
424	            let realized = path
425	                .realize(root)
426	                .map_err(|err| eco_format!("failed to realize path ({err})"))?;
427	
428	            if let Some(parent) = realized.parent() {
429	                std::fs::create_dir_all(parent)
430	                    .map_err(|err| eco_format!("failed to create directory ({err})"))?;
431	            }
432	
433	            std::fs::write(&realized, data)
434	                .map_err(|err| eco_format!("failed to write file ({err})"))?;
435	            Ok(Output::Path(realized))
436	        })
437	        .collect()
438	}
