1	use std::io::{self, Cursor, Read, Write};
2	use std::path::PathBuf;
3	use std::{env, fs};
4	
5	use ecow::eco_format;
6	use semver::Version;
7	use serde::Deserialize;
8	use tempfile::NamedTempFile;
9	use typst::diag::{StrResult, bail};
10	use typst_kit::downloader::Downloader;
11	use xz2::bufread::XzDecoder;
12	use zip::ZipArchive;
13	
14	use crate::args::UpdateCommand;
15	use crate::download;
16	
17	const TYPST_GITHUB_ORG: &str = "typst";
18	const TYPST_REPO: &str = "typst";
19	
20	/// Determine the asset to download based on the target platform.
21	///
22	/// See `.github/workflows/release.yml` for the list of prebuilt assets.
23	macro_rules! determine_asset {
24	    () => {
25	        // For some platforms, only some targets are prebuilt in the release.
26	        determine_asset!(__impl: {
27	            "x86_64-unknown-linux-gnu" => "x86_64-unknown-linux-musl",
28	            "aarch64-unknown-linux-gnu" => "aarch64-unknown-linux-musl",
29	            "armv7-unknown-linux-gnueabi" => "armv7-unknown-linux-musleabi",
30	            "riscv64gc-unknown-linux-musl" => "riscv64gc-unknown-linux-gnu",
31	        })
32	    };
33	
34	    (__impl: { $($origin:literal => $target:literal),* $(,)? }) => {
35	        match env!("TARGET") {
36	            $($origin => concat!("typst-", $target),)*
37	            _ => concat!("typst-", env!("TARGET")),
38	        }
39	    };
40	}
41	
42	/// Self update the Typst CLI binary.
43	///
44	/// Fetches a target release or the latest release (if no version was specified)
45	/// from GitHub, unpacks it and self replaces the current binary with the
46	/// pre-compiled asset from the downloaded release.
47	pub fn update(command: &UpdateCommand) -> StrResult<()> {
48	    if let Some(ref version) = command.version {
49	        let current_tag = typst::utils::version().raw().parse().unwrap();
50	
51	        if version < &Version::new(0, 8, 0) {
52	            eprintln!(
53	                "note: versions older than 0.8.0 will not have \
54	                 the update command available."
55	            );
56	        }
57	
58	        if !command.force && version < &current_tag {
59	            bail!(
60	                "downgrading requires the --force flag: \
61	                `typst update <VERSION> --force`",
62	            );
63	        }
64	    }
65	
66	    // Full path to the backup file.
67	    let backup_path = command.backup_path.clone().map(Ok).unwrap_or_else(backup_path)?;
68	
69	    if let Some(backup_dir) = backup_path.parent() {
70	        fs::create_dir_all(backup_dir)
71	            .map_err(|err| eco_format!("failed to create backup directory ({err})"))?;
72	    }
73	
74	    if command.revert {
75	        if !backup_path.exists() {
76	            bail!(
77	                "unable to revert, no backup found (searched at {})",
78	                backup_path.display(),
79	            );
80	        }
81	
82	        return self_replace::self_replace(&backup_path)
83	            .and_then(|()| fs::remove_file(&backup_path))
84	            .map_err(|err| eco_format!("failed to revert to backup ({err})"));
85	    }
86	
87	    let current_exe = env::current_exe().map_err(|err| {
88	        eco_format!("failed to locate path of the running executable ({err})")
89	    })?;
90	
91	    fs::copy(current_exe, &backup_path)
92	        .map_err(|err| eco_format!("failed to create backup ({err})"))?;
93	
94	    let downloader = download::downloader();
95	
96	    let release = Release::from_tag(command.version.as_ref(), &downloader)?;
97	    if !update_needed(&release)? && !command.force {
98	        eprintln!("Already up-to-date.");
99	        return Ok(());
100	    }
101	
102	    let binary_data = release.download_binary(determine_asset!(), &downloader)?;
103	    let mut temp_exe = NamedTempFile::new()
104	        .map_err(|err| eco_format!("failed to create temporary file ({err})"))?;
105	    temp_exe
106	        .write_all(&binary_data)
107	        .map_err(|err| eco_format!("failed to write binary data ({err})"))?;
108	
109	    self_replace::self_replace(&temp_exe).map_err(|err| {
110	        fs::remove_file(&temp_exe).ok();
111	        eco_format!("failed to self-replace running executable ({err})")
112	    })
113	}
114	
115	/// Assets belonging to a GitHub release.
116	///
117	/// Primarily used to download pre-compiled Typst CLI binaries.
118	#[derive(Debug, Deserialize)]
119	struct Asset {
120	    name: String,
121	    browser_download_url: String,
122	}
123	
124	/// A GitHub release.
125	#[derive(Debug, Deserialize)]
126	struct Release {
127	    tag_name: String,
128	    assets: Vec<Asset>,
129	}
130	
131	impl Release {
132	    /// Download the target release, or latest if version is `None`, from the
133	    /// Typst repository.
134	    pub fn from_tag(
135	        tag: Option<&Version>,
136	        downloader: &dyn Downloader,
137	    ) -> StrResult<Release> {
138	        let url = match tag {
139	            Some(tag) => format!(
140	                "https://api.github.com/repos/{TYPST_GITHUB_ORG}/{TYPST_REPO}/releases/tags/v{tag}"
141	            ),
142	            None => format!(
143	                "https://api.github.com/repos/{TYPST_GITHUB_ORG}/{TYPST_REPO}/releases/latest",
144	            ),
145	        };
146	
147	        match downloader.download(&"release information", &url) {
148	            Ok(data) => serde_json::from_slice(&data).map_err(|err| {
149	                eco_format!("failed to parse release information ({err})")
150	            }),
151	            Err(err) if err.kind() == io::ErrorKind::NotFound => {
152	                bail!("release not found (searched at {url})")
153	            }
154	            Err(err) => bail!("failed to download release ({err})"),
155	        }
156	    }
157	
158	    /// Download the binary from a given [`Release`] and select the
159	    /// corresponding asset for this target platform, returning the raw binary
160	    /// data.
161	    pub fn download_binary(
162	        &self,
163	        asset_name: &str,
164	        downloader: &dyn Downloader,
165	    ) -> StrResult<Vec<u8>> {
166	        let asset = self.assets.iter().find(|a| a.name.starts_with(asset_name)).ok_or(
167	            eco_format!(
168	                "could not find prebuilt binary `{asset_name}` for your platform"
169	            ),
170	        )?;
171	
172	        let data = match downloader.download(&"release", &asset.browser_download_url) {
173	            Ok(data) => data,
174	            Err(err) if err.kind() == io::ErrorKind::NotFound => {
175	                bail!("asset not found (searched for {})", asset.name);
176	            }
177	            Err(err) => bail!("failed to download asset ({err})"),
