412	/// Turns an environment variable string into a boolean value.
413	fn parse_bool(cmd: &Command, val: &str, key: &'static str) -> Option<bool> {
414	    match BoolValueParser::new().parse_ref(cmd, None, val.as_ref()) {
415	        Ok(bool) => Some(bool),
416	        Err(_) => {
417	            crate::print_error(&format!(
418	                "invalid value `{val}` for `{key}`, expected `true` or `false`."
419	            ))
420	            .map_err(|e| eco_format!("{e}"))
421	            .expect("failed to print error");
422	            None
423	        }
424	    }
425	}
426	
427	/// Turns a comma separated list of feature names into a well typed struct of
428	/// feature flags.
429	fn parse_features(feature_list: &str) -> StrResult<Features> {
430	    let mut features = Features { html: false, bundle: false, a11y_extras: false };
431	
432	    for feature in feature_list.split(',').filter(|s| !s.is_empty()) {
433	        match Feature::from_str(feature, true) {
434	            Ok(feature) => match feature {
435	                Feature::Html => features.html = true,
436	                Feature::Bundle => features.bundle = true,
437	                Feature::A11yExtras => features.a11y_extras = true,
438	            },
439	            Err(_) => {
440	                crate::print_error(&format!("unknown runtime feature: `{feature}`"))
441	                    .map_err(|e| eco_format!("{e}"))?;
442	            }
443	        }
444	    }
445	
446	    Ok(features)
447	}
