449	/// A for formatting human readable key-value-description triplets.
450	struct KeyValDesc<'a> {
451	    key: &'static str,
452	    val: Value<'a>,
453	    desc: &'static str,
454	}
455	
456	impl KeyValDesc<'_> {
457	    /// Formatted this as `<key> <val> (<desc>)` with optional right padding for
458	    /// key and value.
459	    fn format(
460	        &self,
461	        out: &mut TermOut,
462	        key_pad: Option<usize>,
463	        val_pad: Option<usize>,
464	    ) -> io::Result<()> {
465	        write!(out, "  ")?;
466	        write_key(out, self.key, key_pad)?;
467	        write!(out, " ")?;
468	        self.val.format(out, val_pad)?;
469	        write!(out, " ({})", self.desc)?;
470	
471	        Ok(())
472	    }
473	}
474	
475	/// A value for colorful human readable formatting.
476	enum Value<'a> {
477	    Unset,
478	    Bool(bool),
479	    Path(&'a Path),
480	    String(&'a str),
481	}
482	
483	impl Value<'_> {
484	    /// Formats this value with optional right padding.
485	    fn format(&self, out: &mut TermOut, pad: Option<usize>) -> io::Result<()> {
486	        match self {
487	            Value::Unset => write_value_special(out, "<unset>", pad),
488	            Value::Bool(true) => write_value_special(out, "on", pad),
489	            Value::Bool(false) => write_value_special(out, "off", pad),
490	            Value::Path(val) => write_value_simple(out, val.display(), pad),
491	            Value::String(val) => write_value_simple(out, val, pad),
492	        }
493	    }
494	}
495	
496	/// Writes a key in cyan with optional right padding.
497	fn write_key(out: &mut TermOut, key: impl Display, pad: Option<usize>) -> io::Result<()> {
498	    out.set_color(ColorSpec::new().set_fg(Some(Color::Cyan)))?;
499	    if let Some(pad) = pad {
500	        write!(out, "{key: <pad$}")?;
501	    } else {
502	        write!(out, "{key}")?;
503	    }
504	    out.reset()?;
505	
506	    Ok(())
507	}
508	
509	/// Writes a value in green with optional right padding.
510	fn write_value_simple(
511	    out: &mut TermOut,
512	    val: impl Display,
513	    pad: Option<usize>,
514	) -> io::Result<()> {
515	    out.set_color(ColorSpec::new().set_fg(Some(Color::Green)))?;
516	    if let Some(pad) = pad {
517	        write!(out, "{val: <pad$}")?;
518	    } else {
519	        write!(out, "{val}")?;
520	    }
521	    out.reset()?;
522	
523	    Ok(())
524	}
