526	/// Writes a special value in blue with optional right padding.
527	fn write_value_special(
528	    out: &mut TermOut,
529	    val: impl Display,
530	    pad: Option<usize>,
531	) -> io::Result<()> {
532	    out.set_color(ColorSpec::new().set_fg(Some(Color::Blue)))?;
533	    if let Some(pad) = pad {
534	        write!(out, "{val: <pad$}")?;
535	    } else {
536	        write!(out, "{val}")?;
537	    }
538	    out.reset()?;
539	
540	    Ok(())
541	}
