543	fn format_human_readable(value: &Info) -> io::Result<()> {
544	    let mut out = terminal::out();
545	
546	    write_key(&mut out, "Version", None)?;
547	    write!(out, " ")?;
548	    write_value_simple(&mut out, value.version, None)?;
549	    write!(out, " (")?;
550	    write_value_simple(&mut out, typst_utils::display_commit(value.build.commit), None)?;
551	    write!(out, ", ")?;
552	    write_value_simple(&mut out, value.build.platform.os, None)?;
553	    write!(out, " on ")?;
554	    write_value_simple(&mut out, value.build.platform.arch, None)?;
555	    writeln!(out, ")\n")?;
556	
557	    writeln!(out, "Build settings")?;
558	    let key_pad = value.build.settings.compile_features().map(|f| f.key.len()).max();
559	    for feature in value.build.settings.compile_features() {
560	        feature.format(&mut out, key_pad, Some(3))?;
561	        writeln!(out)?;
562	    }
563	
564	    writeln!(out)?;
565	    writeln!(out, "Features")?;
566	    let key_pad = value.features.features().map(|f| f.key.len()).max();
567	    for feature in value.features.features() {
568	        feature.format(&mut out, key_pad, Some(3))?;
569	        writeln!(out)?;
570	    }
571	
572	    writeln!(out)?;
573	    writeln!(out, "Fonts")?;
574	    write!(out, "  ")?;
575	    write_key(&mut out, "Custom font paths", None)?;
576	    if value.fonts.paths.is_empty() {
577	        write!(out, " ")?;
578	        write_value_special(&mut out, "<none>", None)?;
579	        writeln!(out)?;
580	    } else {
581	        writeln!(out)?;
582	        for path in value.fonts.custom_paths() {
583	            write!(out, "    - ")?;
584	            path.format(&mut out, None)?;
585	            writeln!(out)?;
586	        }
587	    }
588	
589	    let key_pad = value.fonts.included().map(|(key, _)| key.len()).max();
590	    for (key, val) in value.fonts.included() {
591	        write!(out, "  ")?;
592	        write_key(&mut out, key, key_pad)?;
593	        write!(out, " ")?;
594	        val.format(&mut out, None)?;
595	        writeln!(out)?;
596	    }
597	
598	    writeln!(out)?;
599	    writeln!(out, "Packages")?;
600	    let key_pad = value.packages.paths().map(|(name, _)| name.len()).max();
601	    for (key, val) in value.packages.paths() {
602	        write!(out, "  ")?;
603	        write_key(&mut out, key, key_pad)?;
604	        write!(out, " ")?;
605	        val.format(&mut out, None)?;
606	        writeln!(out)?;
607	    }
608	
609	    writeln!(out)?;
610	    writeln!(out, "Environment variables")?;
611	    let key_pad = value.env.vars().map(|(name, _)| name.len()).max();
612	    for (key, val) in value.env.vars() {
613	        write!(out, "  ")?;
614	        write_key(&mut out, key, key_pad)?;
615	        write!(out, " ")?;
616	        val.format(&mut out, None)?;
617	
618	        writeln!(out)?;
619	    }
620	
621	    Ok(())
622	}
