268	impl CommandExt for Command {
269	    #[track_caller]
270	    fn must_succeed(&mut self) -> TestOutput {
271	        let output = self.output().unwrap();
272	        assert!(
273	            output.status.success(),
274	            "process failed ({}):\n{}",
275	            output.status,
276	            Stream(output.stderr),
277	        );
278	        output.into()
279	    }
280	
281	    #[track_caller]
282	    fn must_fail(&mut self) -> TestOutput {
283	        let output = self.output().unwrap();
284	        assert!(!output.status.success(), "process succeeded ({})", output.status);
285	        output.into()
286	    }
287	}
