308	struct TempFs(TempDir);
309	
310	impl TempFs {
311	    fn path(&self) -> &Path {
312	        self.0.path()
313	    }
314	
315	    fn resolve(&self, path: impl AsRef<Path>) -> PathBuf {
316	        self.path().join(path)
317	    }
318	
319	    #[track_caller]
320	    fn write(&self, path: impl AsRef<Path>, data: impl AsRef<[u8]>) -> PathBuf {
321	        let full = self.resolve(path);
322	        if let Some(parent) = full.parent() {
323	            std::fs::create_dir_all(parent).unwrap();
324	        }
325	        std::fs::write(&full, data).unwrap();
326	        full
327	    }
328	
329	    #[track_caller]
330	    fn read(&self, path: impl AsRef<Path>) -> Stream<Vec<u8>> {
331	        Stream(std::fs::read(self.resolve(path)).unwrap())
332	    }
333	}
