335	struct Stream<T = Vec<u8>>(T);
336	
337	impl<T: AsRef<[u8]>> Stream<T> {
338	    #[track_caller]
339	    fn must_contain(&self, data: impl Debug + AsRef<[u8]>) -> &Self {
340	        assert!(self.contains(data.as_ref()), "{self:?} did not contain {data:?}",);
341	        self
342	    }
343	
344	    #[track_caller]
