346	        assert!(
347	            self.0.as_ref().starts_with(data.as_ref()),
348	            "{self:?} did not start with {data:?}",
349	        );
350	        self
351	    }
352	
353	    #[track_caller]
354	    fn must_match_lines<'s>(&self, lines: impl IntoIterator<Item = &'s str>) -> &Self {
355	        assert_eq!(
356	            self.lines().collect::<Vec<_>>(),
357	            lines.into_iter().collect::<Vec<_>>(),
358	        );
359	        self
360	    }
361	
362	    fn contains(&self, data: impl AsRef<[u8]>) -> bool {
363	        memchr::memmem::find(self.0.as_ref(), data.as_ref()).is_some()
364	    }
365	
366	    fn lines(&self) -> impl Iterator<Item = &str> {
367	        std::str::from_utf8(self.0.as_ref())
368	            .unwrap_or_else(|_| panic!("{self} is not valid utf-8"))
369	            .lines()
